buggyCode:
// Bucket policy của txn-exports (tài khoản Data)
{
  "Effect": "Allow",
  "Principal": { "AWS": "arn:aws:iam::444455556666:role/reporting-task" },
  "Action": ["s3:ListBucket", "s3:GetObject"],
  "Resource": ["arn:aws:s3:::txn-exports", "arn:aws:s3:::txn-exports/*"]
}

// Permission policy của role reporting-task (tài khoản Analytics)
{
  "Effect": "Allow",
  "Action": ["s3:ListBucket", "s3:GetObject"],
  "Resource": ["arn:aws:s3:::txn-exports", "arn:aws:s3:::txn-exports/*"]
}

// Key policy của alias/txn-exports (tài khoản Data), chỉ có statement mặc định
{
  "Sid": "Enable IAM User Permissions",
  "Effect": "Allow",
  "Principal": { "AWS": "arn:aws:iam::111122223333:root" },
  "Action": "kms:*",
  "Resource": "*"
}

fix.code:
// Thêm vào key policy của alias/txn-exports (tài khoản Data)
{
  "Sid": "AllowReportingDecryptViaS3",
  "Effect": "Allow",
  "Principal": { "AWS": "arn:aws:iam::444455556666:role/reporting-task" },
  "Action": "kms:Decrypt",
  "Resource": "*",
  "Condition": {
    "StringEquals": { "kms:ViaService": "s3.ap-southeast-1.amazonaws.com" }
  }
}

// Thêm vào permission policy của role reporting-task (tài khoản Analytics)
{
  "Effect": "Allow",
  "Action": "kms:Decrypt",
  "Resource": "arn:aws:kms:ap-southeast-1:111122223333:key/7c1a...",
  "Condition": {
    "StringEquals": { "kms:ViaService": "s3.ap-southeast-1.amazonaws.com" }
  }
}

// Và thu hẹp quyền S3 của role về đúng prefix cần đọc
// "Resource": "arn:aws:s3:::txn-exports/2026/*"
